import { useEffect } from 'react';
import Pasta from '../../assets/images/pasta.avif';
import Leaf1 from '../../assets/images/leaf1.avif';
import Leaf2 from '../../assets/images/leaf2.avif';
import Leaf3 from '../../assets/images/leaf3.avif';
import Leaf4 from '../../assets/images/leaf4.avif';

import gsap from 'gsap';
import '../../styles/Section1Style.css';

const Section1 = () => {
  useEffect(() => {
    // Xuất hiện ban đầu
    gsap.fromTo(
      ".leaf",
      { opacity: 0, scale: 0 },
      {
        opacity: 1,
        scale: 1,
        duration: 1,
        stagger: 0.2,
        ease: "back.out(1.7)",
        onComplete: () => {
          // Hiệu ứng trôi lơ lửng sau khi hiện ra
          gsap.to(".leaf", {
            y: "random(-20, 20)",
            x: "random(-10, 10)",
            rotation: "random(-15, 15)",
            duration: 2,
            repeat: -1,
            yoyo: true,
            ease: "sine.inOut"
          });
        }
      }
    );
  }, []);

  return (
    <section className="hero_section">
      {/* 1. Lớp nền chữ chạy */}
      <div className="hero_marquee">
        <div className="marquee_track">
          <h1>L'EREDITÀ L'EREDITÀ L'EREDITÀ L'EREDITÀ</h1>
          <h1>L'EREDITÀ L'EREDITÀ L'EREDITÀ L'EREDITÀ</h1>
        </div>
      </div>

      {/* 2. Lớp đĩa mì - Chỉ chứa mì */}
      <div className="pasta_overlay">
        <img src={Pasta} className="pasta" alt="pasta" />
      </div>

      {/* 3. Lớp lá - Nằm ngoài pasta_overlay để căn theo hero_section */}
      <img src={Leaf1} className="leaf leaf1" alt="leaf" />
      <img src={Leaf2} className="leaf leaf2" alt="leaf" />
      <img src={Leaf3} className="leaf leaf3" alt="leaf" />
      <img src={Leaf4} className="leaf leaf4" alt="leaf" />

      {/* 4. Text bên phải */}
      <div className="hero_text text-end">
        <h2>
          Dangerously delicious, so good that our dishes even speak Italian.
        </h2>
      </div>
    </section>
  );
};

export default Section1;
